import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

import { describe, expect, it } from "vitest";

import { renderAbc } from "../src/compat/index.js";

/**
 * **`tune.makeVoicesArray()` — abcjs's LAYOUT ELEMENTS, COLUMN BY COLUMN.**
 *
 * The oracle is `tests/corpus-voices-array/golden.json`, generated by RUNNING abcjs 6.7.0
 * over EVERY in-repo fixture (`scripts/harvest-abcjs-voices-array.mjs`). Each row is the
 * four the walk itself produces — `top`, `height`, `line`, `measureNumber` — and the six
 * fields of the element that `addElementToEvents` then reads: `type`, `x`, `w`,
 * `duration`, and the `abcelem`'s two characters.
 *
 * **THE ROWS ARE COMPARED IN ORDER AND THE ORDER IS THE DRAWING'S**, so a missing element
 * misaligns everything after it and the gate says where. `elemset` is not compared:
 * abcjs's entries are SVG nodes and ours are the `abcelem` itself, which is stated in
 * `voices-array.ts` — the compat layer emits markup as a string and keeps no nodes.
 */
type Row = [
  number,
  number,
  number,
  number,
  number,
  string,
  number,
  number,
  number | null,
  number | null,
  number | null,
];

const GOLDEN = JSON.parse(
  readFileSync(
    join(import.meta.dirname, "corpus-voices-array", "golden.json"),
    "utf-8",
  ),
) as Record<string, Row[]>;

const IN_REPO = join(import.meta.dirname, "corpus-abcjs", "fixtures");

const ours = (slug: string): Row[] => {
  const abc = readFileSync(join(IN_REPO, `${slug}.abc`), "utf-8");
  const tune = renderAbc(["*"], abc, {})[0];
  if (tune === undefined) return [];
  const rows: Row[] = [];
  tune.makeVoicesArray().forEach((voice, v) => {
    for (const row of voice) {
      const el = row.elem;
      const bag = el.abcelem as Record<string, unknown>;
      rows.push([
        v,
        row.top,
        row.height,
        row.line,
        row.measureNumber,
        el.type,
        el.x,
        el.w,
        el.duration,
        (bag["startChar"] as number | undefined) ?? null,
        (bag["endChar"] as number | undefined) ?? null,
      ]);
    }
  });
  return rows;
};

interface Case {
  readonly slug: string;
  readonly agree: number;
  readonly total: number;
  readonly first: string;
}

const table = (): Case[] =>
  Object.entries(GOLDEN).map(([slug, want]) => {
    const got = ours(slug);
    let agree = 0;
    let first = "";
    for (let i = 0; i < Math.max(want.length, got.length); i += 1) {
      if (JSON.stringify(want[i]) === JSON.stringify(got[i])) agree += 1;
      else if (first === "")
        first = `row ${i}: abcjs ${JSON.stringify(want[i])} ours ${JSON.stringify(got[i])}`;
    }
    return { slug, agree, total: want.length, first };
  });

