describe("makeVoicesArray — the layout elements a host is handed", () => {
  const rows = table();

  it("writes the ranked table", () => {
    const off = rows.filter((r) => r.agree < r.total);
    const agree = rows.reduce((t, r) => t + r.agree, 0);
    const total = rows.reduce((t, r) => t + r.total, 0);
    writeFileSync(
      "/tmp/abcts-voices-array-ranked.txt",
      `${[
        `${off.length} of ${rows.length} tunes differ; ${agree} of ${total} rows agree`,
        "",
        ...off.map(
          (r) => `  ${r.slug.padEnd(52)} ${r.agree}/${r.total}  ${r.first}`,
        ),
      ].join("\n")}\n`,
    );
    expect(rows.length).toBeGreaterThan(150);
  });

  it("every ratcheted tune agrees on every row", () => {
    const broken = rows
      .filter((r) => PASSING.includes(r.slug) && r.agree < r.total)
      .map((r) => `${r.slug} ${r.agree}/${r.total} ${r.first}`);
    expect(broken.slice(0, 10)).toEqual([]);
  });

  it("nothing outside the ratchet has quietly started passing", () => {
    const arrived = rows
      .filter((r) => !PASSING.includes(r.slug) && r.agree === r.total)
      .map((r) => r.slug);
    expect(arrived.length, `${arrived.length} tunes now agree — re-ratchet`).toBe(
      0,
    );
  });
});
